sol = [0, 12, 3, 7, 10, 4, 2, 9, 11, 6, 8, 1, 5]
n = 13
# Check fixed
assert sol[1] == 12
assert sol[11] == 1
# Check no attacks
for i in range(n):
    for j in range(i+1, n):
        if sol[i] == sol[j] or abs(sol[i] - sol[j]) == abs(i - j):
            print(f"Conflict: ({i},{sol[i]}) and ({j},{sol[j]})")
            raise SystemExit(1)
print("All good!")
# Print board
for r in range(n):
    line = ""
    for c in range(n):
        if sol[r] == c:
            line += "Q "
        else:
            line += ". "
    print(line)
